const ease = (frame: number, from: number, to: number) =>
  interpolate(frame, [from, to], [0, 1], {
    easing: Easing.bezier(0.2, 0.82, 0.22, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

const popAt = (frame: number, start: number, fps: number) =>
  frame < start
    ? 0
    : spring({
        frame: frame - start,
        fps,
        config: {damping: 13, stiffness: 150, mass: 0.72},
      });

const Check: React.FC<{size?: number; color?: string; stroke?: number}> = ({
  size = 28,
  color = "white",
  stroke = 4,
}) => (
  <svg width={size} height={size} viewBox="0 0 32 32" fill="none">
    <path
      d="M7 16.5l6 6L25.5 9.5"
      stroke={color}
      strokeWidth={stroke}
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

