const StepCard: React.FC<{step: StepSpec; index: number}> = ({step, index}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const pop = popAt(frame, step.start, fps);
  const settled = ease(frame, step.start + 22, step.start + 54);
  const complete = ease(frame, step.start + 42, step.start + 66);
  const secondPass = ease(frame, 552 + index * 52, 568 + index * 52) *
    (1 - ease(frame, 604 + index * 52, 626 + index * 52));
  const breathe = frame > step.start + 55 ? Math.sin((frame - step.start) * 0.035 + index) : 0;
  const lift = secondPass * 18 + Math.max(0, breathe) * 2.5;
  const tilt = (1 - settled) * (index % 2 === 0 ? -7 : 7) + secondPass * (index % 2 === 0 ? 2.5 : -2.5);

  const actionFrame = frame - step.start;
  let iconX = 0;
  let iconY = 0;
  let iconRotation = 0;
  let iconScale = 1;
  if (step.icon === "select" && actionFrame > 24) {
    iconRotation = Math.sin(actionFrame * 0.08) * 0.9;
    iconScale += Math.max(0, Math.sin(actionFrame * 0.055)) * 0.012;
  }
  if (step.icon === "cart" && actionFrame > 8 && actionFrame < 70) {
    iconY = -Math.abs(Math.sin((actionFrame - 8) * 0.12)) * 9 * (1 - complete);
  }
  if (step.icon === "address" && actionFrame > 22) {
    iconY = -Math.max(0, Math.sin((actionFrame - 22) * 0.06)) * 3.5;
    iconRotation = Math.sin(actionFrame * 0.035) * 0.7;
  }
  if (step.icon === "payment" && actionFrame > 18) {
    iconScale += Math.max(0, Math.sin((actionFrame - 18) * 0.07)) * 0.014;
  }
  if (step.icon === "delivery") {
    iconX = (1 - ease(frame, step.start, step.start + 44)) * 150;
    if (actionFrame > 52) iconY = Math.sin(actionFrame * 0.115) * 2.2;
  }

  return (
    <>
      <div
        style={{
          position: "absolute",
          left: step.x - 141,
          top: 270 - lift,
          width: 282,
          height: 336,
          borderRadius: 34,
          background: `linear-gradient(145deg, rgba(255,255,255,.98), ${step.tint})`,
          border: "1px solid rgba(23,47,79,.075)",
          boxShadow: secondPass > 0.01
            ? `0 28px 70px rgba(23,47,79,.16), 0 0 0 ${6 + secondPass * 5}px ${step.accent}22`
            : "0 24px 58px rgba(23,47,79,.105), inset 0 1px 0 white",
          opacity: pop,
          transform: `perspective(900px) rotateY(${tilt}deg) scale(${0.72 + pop * 0.28})`,
          transformOrigin: "50% 80%",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            width: 170,
            height: 170,
            borderRadius: "50%",
            background: `${step.accent}18`,
            filter: "blur(1px)",
            left: 56,
            top: 59,
            transform: `scale(${1 + secondPass * 0.15})`,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: 22,
            top: 18,
            padding: "7px 11px",
            borderRadius: 999,
            color: step.accent,
            background: `${step.accent}14`,
            fontFamily: "Arial, Helvetica, sans-serif",
            fontSize: 12,
            fontWeight: 900,
            letterSpacing: 1.7,
          }}
        >
          STEP 0{step.number}
        </div>
        <Img
          src={ICONS[step.icon]}
          style={{
            position: "absolute",
            left: 1,
            top: 22,
            width: 280,
            height: 280,
            objectFit: "contain",
            filter: "drop-shadow(0 15px 16px rgba(23,47,79,.12))",
            transform: `translate(${iconX}px, ${iconY}px) rotate(${iconRotation}deg) scale(${iconScale})`,
          }}
        />
        <div
          style={{
            position: "absolute",
            left: 22,
            right: 22,
            bottom: 17,
            height: 4,
            borderRadius: 10,
            background: "rgba(23,47,79,.07)",
            overflow: "hidden",
          }}
        >
          <div
            style={{
              width: `${complete * 100}%`,
              height: "100%",
              borderRadius: 10,
              background: step.accent,
            }}
          />
        </div>
      </div>

      <div
        style={{
          position: "absolute",
          left: step.x - 34,
          top: LINE_Y - 34,
          width: 68,
          height: 68,
          borderRadius: "50%",
          display: "grid",
          placeItems: "center",
          color: "white",
          background: complete > 0.98 ? step.accent : "#ffffff",
          border: `5px solid ${complete > 0.98 ? step.accent : "#d9e0e7"}`,
          boxShadow: complete > 0.98
            ? `0 8px 24px ${step.accent}55, 0 0 0 ${secondPass * 11}px ${step.accent}18`
            : "0 7px 19px rgba(23,47,79,.10)",
          fontFamily: "Arial, Helvetica, sans-serif",
          fontWeight: 900,
          fontSize: 24,
          opacity: pop,
          transform: `scale(${0.72 + pop * 0.28 + secondPass * 0.06})`,
        }}
      >
        {complete > 0.98 ? <Check size={29} stroke={4.3} /> : step.number}
      </div>

      <div
        style={{
          position: "absolute",
          left: step.x - 166,
          top: 787,
          width: 332,
          textAlign: "center",
          opacity: pop,
          transform: `translateY(${(1 - settled) * 16}px)`,
          fontFamily: "Arial, Helvetica, sans-serif",
        }}
      >
        <div
          style={{
            color: "#172f4f",
            fontSize: 27,
            lineHeight: 1.1,
            fontWeight: 900,
            letterSpacing: -0.7,
          }}
        >
          {step.title}
        </div>
        <div
          style={{
            color: "#7b8796",
            fontSize: 14,
            lineHeight: 1.2,
            marginTop: 10,
            fontWeight: 700,
            letterSpacing: 1.15,
            textTransform: "uppercase",
          }}
        >
          {step.detail}
        </div>
      </div>
    </>
  );
};

const ProgressRail: React.FC = () => {
  const frame = useCurrentFrame();
  const progress = ease(frame, 68, 488);
  const railWidth = LINE_RIGHT - LINE_LEFT;
  const activeWave = frame > 510 ? ((frame - 510) % 310) / 310 : 0;

  return (
    <>
      <div
        style={{
          position: "absolute",
          left: LINE_LEFT,
          top: LINE_Y - 6,
          width: railWidth,
          height: 12,
          borderRadius: 20,
          background: "#e3e7ea",
          boxShadow: "inset 0 2px 4px rgba(23,47,79,.08)",
        }}
      />
      <div
        style={{
          position: "absolute",
          left: LINE_LEFT,
          top: LINE_Y - 6,
          width: railWidth * progress,
          height: 12,
          borderRadius: 20,
          background: "linear-gradient(90deg, #ff5b4d 0%, #ff8a34 27%, #13b8b6 57%, #2878d8 79%, #ff5b4d 100%)",
          boxShadow: "0 0 22px rgba(255,91,77,.18)",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            width: 190,
            height: "100%",
            background: "linear-gradient(90deg, transparent, rgba(255,255,255,.82), transparent)",
            transform: `translateX(${railWidth * activeWave - 160}px)`,
          }}
        />
      </div>
      {Array.from({length: 5}, (_, index) => {
        const t = frame < 90 ? -1 : (((frame - 90 - index * 57) % 330) + 330) % 330 / 330;
        const visible = frame > 90 && t < progress + 0.025;
        const x = LINE_LEFT + railWidth * t;
        return (
          <div
            key={index}
            style={{
              position: "absolute",
              left: x - 7,
              top: LINE_Y - 7,
              width: 14,
              height: 14,
              borderRadius: 4,
              background: index % 2 === 0 ? "#fff7ec" : "#ffffff",
              border: "2px solid rgba(23,47,79,.28)",
              boxShadow: "0 4px 8px rgba(23,47,79,.18)",
              opacity: visible ? 1 : 0,
              transform: `rotate(45deg) scale(${0.82 + 0.18 * Math.sin(frame * 0.08 + index)})`,
            }}
          />
        );
      })}
    </>
  );
};

