const Sparkles: React.FC = () => {
  const frame = useCurrentFrame();
  const points = [
    {x: 167, y: 232, phase: 0.2, color: "#ff5b4d"},
    {x: 1764, y: 246, phase: 1.8, color: "#13b8b6"},
    {x: 1830, y: 690, phase: 2.7, color: "#ff8a34"},
    {x: 98, y: 664, phase: 4.2, color: "#2878d8"},
    {x: 490, y: 202, phase: 5.1, color: "#ff8a34"},
    {x: 1440, y: 198, phase: 3.6, color: "#ff5b4d"},
  ];
  return (
    <>
      {points.map((point, index) => {
        const pulse = 0.5 + 0.5 * Math.sin(frame * 0.055 + point.phase);
        return (
          <div
            key={index}
            style={{
              position: "absolute",
              left: point.x,
              top: point.y,
              width: 16,
              height: 16,
              opacity: 0.25 + pulse * 0.45,
              transform: `rotate(${frame * 0.16 + index * 25}deg) scale(${0.7 + pulse * 0.35})`,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 7,
                top: 0,
                width: 2,
                height: 16,
                borderRadius: 4,
                background: point.color,
              }}
            />
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 7,
                width: 16,
                height: 2,
                borderRadius: 4,
                background: point.color,
              }}
            />
          </div>
        );
      })}
    </>
  );
};

export const Motion: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const panelIn = popAt(frame, 0, fps);
  const camera = 1.055 - ease(frame, 0, 92) * 0.055;
  const completionBreath = frame > 760 ? Math.sin((frame - 760) * 0.025) * 0.0025 : 0;

  return (
    <AbsoluteFill style={{background: "#f7f3ea"}}>
      <Background />
      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `scale(${camera + completionBreath})`,
          transformOrigin: "50% 50%",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 60,
            top: 70,
            width: 1800,
            height: 940,
            borderRadius: 52,
            background: "rgba(255,255,255,.93)",
            border: "1px solid rgba(255,255,255,.9)",
            boxShadow: "0 38px 92px rgba(23,47,79,.13), inset 0 1px 0 white",
            opacity: panelIn,
            transform: `translateY(${(1 - panelIn) * 44}px) scale(${0.965 + panelIn * 0.035})`,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: 0,
              height: 12,
              background: "linear-gradient(90deg, #ff5b4d, #ff8a34 28%, #13b8b6 58%, #2878d8 80%, #ff5b4d)",
            }}
          />
          <div
            style={{
              position: "absolute",
              left: 84,
              right: 84,
              top: 220,
              height: 1,
              background: "linear-gradient(90deg, transparent, rgba(23,47,79,.10), transparent)",
            }}
          />
        </div>
        <Header />
        <ProgressRail />
        {STEPS.map((step, index) => (
          <StepCard key={step.number} step={step} index={index} />
        ))}
        <CompletionBadge />
        <Sparkles />
      </div>
    </AbsoluteFill>
  );
};
